import sys
from collections import defaultdict, deque
import heapq

def solve():
    lines = sys.stdin.read().splitlines()
    idx = 0
    first_case = True

    while idx < len(lines):
        line = lines[idx].strip()
        if not line:
            idx += 1
            continue
        try:
            n = int(line)
        except ValueError:
            idx += 1
            continue

        if n == 0:
            break

        idx += 1
        packages = []
        deps_map = {}

        for _ in range(n):
            parts = lines[idx].split()
            idx += 1
            pkg = parts[0]
            deps = parts[1:] if len(parts) > 1 else []
            packages.append(pkg)
            deps_map[pkg] = deps

        adj = defaultdict(list)
        in_degree = {pkg: 0 for pkg in packages}

        for pkg in packages:
            for dep in deps_map[pkg]:
                if dep in packages:
                    adj[dep].append(pkg)
                    in_degree[pkg] += 1

        heap = []
        for pkg in packages:
            if in_degree[pkg] == 0:
                heapq.heappush(heap, pkg)

        result = []
        processed = set()

        while heap:
            current = heapq.heappop(heap)
            result.append(current)
            processed.add(current)

            for neighbor in adj[current]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    heapq.heappush(heap, neighbor)

        if len(result) != n:
            if not first_case:
                print()
            print("cannot be ordered")
        else:
            if not first_case:
                print()
            for pkg in result:
                print(pkg)

        first_case = False

solve()
